(function(){
  'use strict';
  const C=window.BranchCore,Q=window.QuestData,W=window.AdventureCore,Store=window.AdventureSave,A='assets/gear/';
  const $=id=>document.getElementById(id),escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const HEROES={femaleAdventurer:{name:'Ava',role:'The curious pathfinder',copy:'Always one good question away from a discovery.'},maleAdventurer:{name:'Max',role:'The determined explorer',copy:'A little courage. A lot of learning by doing.'}};
  const loaded=Store.load();let S=loaded.value,project=W.projectFor(S.level,S);
  const region=()=>W.REGIONS[S.level],levelData=()=>Q.LEVELS[S.level],noteList=()=>W.notes(S.level,S);
  const G={mode:null,keys:new Set(),path:[],camera:{x:0,y:0},near:null,encounter:null,record:null,result:null,panel:'tree',trace:0,chestOpen:false,timer:null,token:0,lastTime:0,stepDistance:0,teacher:location.hash==='#teacher',keyboard:false,selected:'r',history:[],records:[],waveResults:[],cursor:0,preview:0,waveDone:false};
  const heroImg=pose=>`${A}heroes/${S.hero}-${pose}.png`,foeImg=f=>`assets/woodland/monsters/${f.kind}${f.values.horns?'-horns':''}.webp`;
  const reduced=()=>S.reduced||matchMedia('(prefers-reduced-motion: reduce)').matches,instant=()=>reduced()||G.keyboard;
  const say=text=>{$('live').textContent=text;};let toastTimer;
  function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3200);}
  function save(){try{Store.write(S);$('save-status').textContent='Adventure saved on this device';}catch{$('save-status').textContent='Save unavailable · export in Settings';}}
  function gear(id,small=false){const g=Q.GEAR[id];return `<span class="gear"><i style="background:${g.color}"><img src="${A}icons/${g.img}.${g.img==='hammer'?'svg':'png'}" alt=""></i>${small?'':escape(g.label)}</span>`;}
  function qtext(id,value){const f=Q.CLUES[id];return f.type==='boolean'?f.question:`Is ${f.name.toLowerCase()} greater than ${value}?`;}
  function chips(foe){return `<div class="feature-chips">${project.features.map(f=>f.id).map(id=>`<span>${escape(Q.CLUES[id].name)} <strong>${typeof foe.values[id]==='boolean'?(foe.values[id]?'Yes':'No'):foe.values[id]}</strong></span>`).join('')}</div>`;}
    function wrap(text, max = 19) {
    const lines = ['']; for (const w of text.split(' ')) { if ((lines[lines.length - 1] + ' ' + w).trim().length > max) lines.push(w); else lines[lines.length - 1] = (lines[lines.length - 1] + ' ' + w).trim(); }
    return lines.slice(0, 3);
  }
  function treeSvg(tree, project, opts = {}) {
    const path = opts.path || [];
    const nodes = C.walk(tree), leaves = nodes.filter(n => !n.split);
    const depth = Math.max(...nodes.map(n => n.depth));
    const NW = 176, NH = 78, ROW = 110;
    const width = Math.max(420, leaves.length * (NW + 16) + 20), height = depth * ROW + NH + 24;
    const pos = new Map(); let li = 0;
    (function locate(n) { const x = n.split ? (locate(n.no) + locate(n.yes)) / 2 : 10 + (li++ + .5) * ((width - 20) / leaves.length); pos.set(n.id, { x, y: 8 + n.depth * ROW }); return x; })(tree);
    const edges = nodes.filter(n => n.split).map(n => ['no', 'yes'].map(b => {
      const p = pos.get(n.id), c = pos.get(n[b].id), on = path.includes(n[b].id) && path.includes(n.id);
      return `<path class="tree-edge ${on ? 'on' : ''}" d="M${p.x},${p.y + NH} C${p.x},${p.y + NH + 30} ${c.x},${c.y - 30} ${c.x},${c.y}"/><text x="${(p.x + c.x) / 2 + (b === 'no' ? -14 : 14)}" y="${(p.y + NH + c.y) / 2 + 4}" text-anchor="middle" font-weight="900" font-size="15" fill="${b === 'no' ? '#a3412a' : '#2f6b22'}">${b === 'no' ? 'No' : 'Yes'}</text>`;
    }).join('')).join('');
    const cards = nodes.map(n => {
      const p = pos.get(n.id), x = p.x - NW / 2, on = path.includes(n.id);
      const rows = C.nodeRows(project, n); const mixed = C.gini(rows, project.labels) > 1e-10;
      if (n.split) {
        const lines = wrap(qtext(n.split.featureId, n.split.threshold));
        return `<g class="tree-node ${on ? 'on' : ''}"><rect x="${x}" y="${p.y}" width="${NW}" height="${NH}" rx="12" fill="#fff8dc"/>${lines.map((l, i) => `<text x="${p.x}" y="${p.y + NH / 2 + 5 + (i - (lines.length - 1) / 2) * 18}" text-anchor="middle">${escape(l)}</text>`).join('')}</g>`;
      }
      const pickable = opts.pick && mixed && n.depth < opts.maxDepth;
      if (pickable) return `<g class="tree-node pick ${opts.selected === n.id ? 'sel' : ''}" data-node="${n.id}" role="button" tabindex="0" aria-label="Mixed group of ${rows.length} notes. Choose a question here."><rect x="${x}" y="${p.y}" width="${NW}" height="${NH}" rx="12" fill="#f6e6c8"/><text x="${p.x}" y="${p.y + 30}" text-anchor="middle">🤔 Mixed group</text><text x="${p.x}" y="${p.y + 52}" text-anchor="middle" font-size="12">${rows.length} notes · pick a question</text></g>`;
      const g = Q.GEAR[Q.gearId(n.prediction)];
      return `<g class="tree-node ${on ? 'on' : ''}"><rect x="${x}" y="${p.y}" width="${NW}" height="${NH}" rx="12" fill="${g.color}22"/><circle cx="${x + 30}" cy="${p.y + NH / 2}" r="20" fill="${g.color}"/><image href="${A}icons/${g.img}.${g.img === 'hammer' ? 'svg' : 'png'}" x="${x + 16}" y="${p.y + NH / 2 - 14}" width="28" height="28"/><text x="${x + 58}" y="${p.y + NH / 2 - 2}">${escape(g.label)}</text><text x="${x + 58}" y="${p.y + NH / 2 + 17}" font-size="12" font-weight="600">${rows.length} notes${mixed ? ' · mixed' : ''}</text></g>`;
    }).join('');
    return `<svg ${opts.pick?`style="width:${Math.max(520,width)}px;height:${Math.max(190,height)}px"`:""} viewBox="0 0 ${width} ${height}" role="group" aria-label="The Wise Tree with ${nodes.filter(n => n.split).length} questions">${edges}${cards}</svg>`;
  }

  let audio=null;
  function sound(kind){if(S.muted)return;try{if(!audio){const ctx=new AudioContext(),master=ctx.createGain(),sfx=ctx.createGain(),ui=ctx.createGain();master.gain.value=.22;sfx.gain.value=.25;ui.gain.value=.12;sfx.connect(master);ui.connect(master);master.connect(ctx.destination);audio={ctx,master,sfx,ui};}const {ctx}=audio;void ctx.resume();const notes={step:[105],open:[330,440,660],hit:[330,495],miss:[196,165],pick:[440]}[kind]||[330];notes.forEach((frequency,i)=>{const osc=ctx.createOscillator(),gain=ctx.createGain(),start=ctx.currentTime+i*.07;osc.type=kind==='step'?'triangle':'sine';osc.frequency.value=frequency;gain.gain.setValueAtTime(.001,start);gain.gain.linearRampToValueAtTime(kind==='step'?.08:.32,start+.012);gain.gain.exponentialRampToValueAtTime(.001,start+.18);osc.connect(gain);gain.connect(kind==='pick'?audio.ui:audio.sfx);osc.start(start);osc.stop(start+.2);osc.onended=()=>{osc.disconnect();gain.disconnect();};});}catch{/* All feedback has a visual equivalent. */}}
  function cancelWork(){clearTimeout(G.timer);G.timer=null;G.token++;G.keys.clear();G.path=[];}
  function schedule(callback,ms){const token=G.token;clearTimeout(G.timer);G.timer=setTimeout(()=>{if(token===G.token)callback();},ms);}
  function closeOverlay(){cancelWork();if(G.encounter)S.position={...G.encounter.returnPoint};G.encounter=null;G.record=null;G.records=[];G.waveResults=[];G.result=null;G.mode=null;$('overlay').close();renderSidebar();paint();updateNearby(true);save();$('world').focus({preventScroll:true});}
  function shell(title,subtitle,body,footer='',wide=true){return `<div class="modal-shell ${wide?'wide':''}"><header class="modal-head"><div><span class="modal-kicker">Tree Quest · ${escape(region().name)}</span><h2 id="overlay-title">${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${S.started?'<button class="icon-button close-button" data-action="close" aria-label="Return to the world">×</button>':''}</header><div class="modal-body">${body}</div>${footer?`<footer class="modal-footer">${footer}</footer>`:''}</div>`;}
  function show(mode,content){G.keys.clear();G.path=[];G.mode=mode;$('overlay-content').innerHTML=content;$('overlay').dataset.mode=mode;$('overlay').classList.toggle('compact',mode==='settings'||mode==='help'||mode==='teacher');if(!$('overlay').open)$('overlay').showModal();const focus=$('overlay-content').querySelector('[data-focus],.modal-footer button:not(:disabled),button[aria-pressed="true"],.close-button');focus?.focus({preventScroll:true});}
  function chooseCharacters(){cancelWork();show('selection',shell('Every adventure needs a hero.','Who will become the Wildwood’s next Treekeeper?',`<div class="character-scene"><div class="character-story"><img src="${A}icons/wise-tree.png" alt="The Wise Tree"><h3>A little wisdom.<br>A grand adventure.</h3><p>The forest is full of surprises. Teach the Wise Tree to choose your equipment, then see where your questions take you.</p><span class="character-story-note">Two heroes. The same curious spirit.</span></div><div class="hero-choices">${Object.entries(HEROES).map(([id,h])=>`<button class="hero-choice" data-hero="${id}" aria-pressed="${S.hero===id}"><span class="hero-stage"><img src="${A}heroes/${id}-idle.png" alt=""></span><span class="hero-choice-name">${h.name}<i>${S.hero===id?'✓':'+'}</i></span><strong>${h.role}</strong><span>${h.copy}</span></button>`).join('')}</div></div>`,`<span>Your questions make the difference. Both heroes play the same way.</span><button class="primary" data-action="begin">${S.started?'Keep exploring':'Begin adventure'} <span aria-hidden="true">↗</span></button>`));}
  function currentFoe(){return G.encounter?.foe||W.wave(S.level,S.trial)[0];}
  function enterEncounter(){if(G.mode)return;if(W.distance(S.position,W.LANDMARKS.monster)>135){travel('monster');return;}if(S.completed.includes(S.trial)){toast('This encounter is complete. Find a fresh wave or journey onward.');return;}cancelWork();const wave=W.wave(S.level,S.trial);G.encounter={foe:wave[0],wave,returnPoint:{...S.position}};G.record=null;G.records=[];G.waveResults=[];G.result=null;S.hearts=3;if(!S.visits.includes('monster'))S.visits.push('monster');save();renderSidebar();inspect();}
  function inspect(){const foe=currentFoe(),wave=G.encounter.wave;show('inspect',shell(wave.length>1?'A wave approaches.':'A creature on the forest trail.',wave.length>1?'One trained tree will choose your equipment for every enemy.':'Look at its clues. Which question could help the Wise Tree?',`<div class="inspect-scene"><div class="monster-portrait"><span class="portrait-sun"></span><img src="${foeImg(foe)}" alt="${escape(foe.name)}"><span class="monster-shadow"></span></div><div class="inspect-details"><span class="section-label">${wave.length} ${wave.length===1?'creature':'enemies'} · ${escape(region().lesson)}</span><h3>${escape(foe.name)}</h3>${chips(foe)}<p>Read ${project.rows.length} scout reports. Build a tree with up to ${S.depth} ${S.depth===1?'question':'questions'} on each path, then put it to the test.</p><div class="note-box">The chest reveals your actual predictions. Every enemy must receive the right gear to clear a wave; hearts let you continue observing after a mistake.</div></div></div>${wave.length>1?'<div class="encounter-lineup">'+wave.map((f,i)=>'<div><img src="'+foeImg(f)+'" alt=""><span>'+(i+1)+'. '+escape(f.name)+'</span>'+chips(f)+'</div>').join('')+'</div>':''}`,`<button class="text-button" data-action="close">Leave it for now</button><button class="primary" data-action="tune">Tune the Wise Tree <span aria-hidden="true">↗</span></button>`));}
  function noteCards(limit=Infinity){return noteList().slice(0,limit).map(n=>{const verified=S.level===3&&S.checked.includes(n.id),original=S.level===3?Q.notes(3).find(row=>row.id===n.id):null,corrected=verified&&original.gear!==n.gear;return `<article class="scout-note"><img src="${foeImg(n)}" alt=""><div><strong>${escape(n.name)}</strong>${chips(n)}<span class="note-label">${S.level===3?(verified?'Verified gear':'Pip’s recorded gear'):'Past successful gear'} ${gear(n.gear)}</span>${S.level===3?'<button class="report-check" data-check="'+n.id+'" '+(verified||S.checked.length>=3?'disabled':'')+'>'+(verified?'✓ Report verified':'Verify report')+'</button>':''}${verified?'<p class="report-verdict">'+(corrected?'Corrected: '+escape(Q.GEAR[original.gear].label)+' → '+escape(Q.GEAR[n.gear].label):'Verified: the recorded gear was correct.')+'</p>':''}</div></article>`;}).join('');}
  function tune(){cancelWork();G.panel='tree';G.selected='r';if(!S.visits.includes('tree'))S.visits.push('tree');save();renderSidebar();renderTune();}
  function rememberTree(){G.history.push(C.copy(S.tree));if(G.history.length>20)G.history.shift();}
  function editableLeaves(){return C.walk(S.tree).filter(n=>!n.split&&n.depth<S.depth&&C.gini(C.nodeRows(project,n),project.labels)>1e-10);}
  function lessonGuidance(){
    if(S.level===0)return 'Compare the hot and cool creatures in the scout reports. Choose one question, then test it on a creature the Tree has not seen.';
    if(S.level===1)return 'One question can only make two gear groups. Set Questions per path to 2 or 3, then select a mixed leaf to grow another question.';
    if(S.level===2)return S.revealed?'The Shadow clue is now visible. Allow 3 questions per path and rebuild using the new clue.':'Your feature list is missing a clue. Use Reveal the missing clue, then rebuild the tree from the updated reports.';
    if(S.level===3)return S.checked.length===3?'All three report checks are used. Rebuild from the verified evidence, or Restart report checks to try again without losing chapter progress.':'Pip may have mislabeled horned stone creatures. Open Scout journal and use Verify report on suspicious notes. Corrected labels reset the tree; verified correct labels keep it. A perfect training score can still miss an unfamiliar combination.';
    return S.scoutRounds===2?'Both expeditions are back with six new shadow reports. Set Questions per path to 3 and rebuild. Check that shadow creatures can reach the Sun Shield, even when they are hot or flying.':'The Tree has too few shadow examples. Use Send scouts for both expeditions, then set Questions per path to 3 and rebuild from the stronger evidence.';
  }
  function evidenceTools(inTree=false){return S.level===2?`<button class="secondary" data-action="reveal-clue" ${S.revealed?'disabled':''}>${S.revealed?'✓ Shadow clue recovered':'Reveal the missing clue'}</button>`:S.level===3?`<span class="evidence-counter">${3-S.checked.length} report checks left</span>${inTree?'<button class="secondary" data-tab="notes">Check scout reports</button>':''}${S.checked.length===3?'<div class="report-retry"><button class="secondary" data-action="retry-reports">Restart report checks</button><small>Restores 3 checks and resets this chapter’s tree. Other chapters stay saved.</small></div>':''}`:S.level===4?`<button class="secondary" data-action="send-scouts" ${S.scoutRounds>=2?'disabled':''}>Send scouts · ${2-S.scoutRounds} expeditions left</button>`:'';}
  function checkReport(id){if(S.level!==3||S.checked.includes(id)||S.checked.length>=3)return;const note=Q.notes(3).find(n=>n.id===id);if(!note)return;S.checked.push(id);if(note.gear!==note.real){rebuildEvidence(note.name+': corrected '+Q.GEAR[note.gear].label+' to '+Q.GEAR[note.real].label+'. Rebuild the tree.');}else{save();toast(note.name+': the recorded gear was correct. Your tree is unchanged.');if(G.mode==='journal')openJournal();else renderTune();}const card=$('overlay-content').querySelector('[data-check="'+id+'"]')?.closest('.scout-note');const verdict=card?.querySelector('.report-verdict');if(verdict){verdict.tabIndex=-1;verdict.focus({preventScroll:true});card.scrollIntoView({block:'nearest',inline:'nearest'});}}
  function restartReports(){if(S.level!==3||S.checked.length<3)return;S.checked=[];rebuildEvidence('Three report checks restored. Recheck the notes and rebuild this chapter’s tree.');}
  function rebuildEvidence(message){project=W.projectFor(S.level,S);S.tree=C.newTree(project);G.history=[];G.selected='r';save();renderSidebar();toast(message);if(G.mode==='journal')openJournal();else renderTune();}
  function renderTune(){
    const score=C.accuracy(S.tree,project.rows,project),leaves=editableLeaves();let node=C.findNode(S.tree,G.selected);if(!node||node.split||node.depth>=S.depth){node=leaves[0]||null;G.selected=node?.id||'r';}const rows=node?C.nodeRows(project,node):[],seen=new Set(),all=node?C.candidates(rows,project.features,project.labels):[],candidates=all.filter(c=>!seen.has(c.featureId)&&seen.add(c.featureId));const foe=currentFoe(),count=C.walk(S.tree).filter(n=>n.split).length;
    const card=c=>`<button class="question-card" data-split="${c.featureId}" data-threshold="${c.threshold??''}"><span>${escape(qtext(c.featureId,c.threshold))}</span><div class="candidate-track"><i style="transform:scaleX(${(rows.length-c.remaining)/Math.max(1,rows.length)})"></i></div><small>Sorts ${rows.length-c.remaining} of ${rows.length} notes in this group</small></button>`;
    const choices=node&&candidates.length?`<div class="branch-heading"><h3>Choose a question for this group</h3><span>${rows.length} notes · depth ${node.depth+1} / ${S.depth}</span></div><p class="muted">Select a mixed leaf above to choose where the next question grows.</p><div class="question-options">${candidates.map(card).join('')}</div>${all.length>candidates.length?'<details class="other-cutoffs"><summary>Explore other numerical cut-offs</summary><div class="question-options">'+all.filter(c=>!candidates.includes(c)).slice(0,12).map(card).join('')+'</div></details>':''}`:`<div class="trained-note"><span>✦</span><div><strong>${score.correct===score.total?'Every training note reaches its gear label.':'This tree has reached its current limit.'}</strong><p>${score.correct===score.total?'Unseen enemies are still the real test.':'Raise the depth limit, check the evidence, or reset and try a different question.'}</p></div></div>`;
    const body=`<div class="teaching-tabs" role="tablist" aria-label="Teaching views"><button id="tab-tree" role="tab" data-tab="tree" aria-controls="teaching-panel" tabindex="${G.panel==='tree'?0:-1}" aria-selected="${G.panel==='tree'}">The Wise Tree</button><button id="tab-notes" role="tab" data-tab="notes" aria-controls="teaching-panel" tabindex="${G.panel==='notes'?0:-1}" aria-selected="${G.panel==='notes'}">Scout journal <span>${project.rows.length}</span></button></div><div id="teaching-panel" role="tabpanel" aria-labelledby="tab-${G.panel}">${G.panel==='notes'?'<div class="journal-intro"><h3>Look for the pattern in the evidence.</h3><p>'+escape(lessonGuidance())+'</p><div class="evidence-tools">'+evidenceTools()+'</div></div><div class="notes-grid">'+noteCards()+'</div>':`<div class="teaching-grid"><section class="tree-workspace"><div class="tree-controls"><label>Questions per path <select id="tree-depth" ${region().maxDepth===1?'disabled':''}>${Array.from({length:region().maxDepth},(_,i)=>'<option value="'+(i+1)+'" '+(S.depth===i+1?'selected':'')+'>'+(i+1)+'</option>').join('')}</select></label><div><button class="secondary" data-action="grow-one" ${!C.nextSplit(S.tree,project,S.depth)?'disabled':''}>Grow one branch</button><button class="secondary" data-action="auto-tree">Auto-grow tree</button><button class="text-button" data-action="undo-tree" ${G.history.length?'':'disabled'}>Undo</button><button class="text-button" data-action="reset-tree">Reset tree</button></div></div><div class="tree-workspace-head"><span><img src="${A}icons/wise-tree.png" alt=""> ${count} ${count===1?'question':'questions'} in your tree</span><span>${score.correct} / ${score.total} notes correct</span></div><div class="tree-canvas" role="region" tabindex="0" aria-label="Decision tree. Scroll to explore branches.">${treeSvg(S.tree,project,{pick:true,maxDepth:S.depth,selected:G.selected})}</div><div class="question-area">${choices}</div><details class="math-details"><summary>How does the Tree learn?</summary><p>Each question divides a group into Yes and No. Each leaf predicts its most common gear label. More questions allow more specific groups, but good training scores do not guarantee success against new enemies.</p>${candidates.map(c=>'<p>'+escape(qtext(c.featureId,c.threshold))+' · Gini improvement: '+c.gain.toFixed(4)+'</p>').join('')}</details></section><aside class="teaching-context"><div class="current-creature"><img src="${foeImg(foe)}" alt=""><span>${G.encounter?'Wave leader':'Waiting on the trail'}</span><h3>${escape(foe.name)}</h3>${chips(foe)}</div><div class="evidence-tools">${evidenceTools(true)}</div><div class="tree-advice"><img src="${A}icons/wise-tree.png" alt=""><p>${escape(lessonGuidance())}</p></div><h4>A peek at the journal</h4><div class="notes-peek">${noteCards(2)}</div><button class="text-button" data-tab="notes">Read all ${project.rows.length} scout notes ↗</button></aside></div>`}</div>`;
    show('tune',shell('Tend the Wise Tree',region().lesson+' · Build a rule from the scouts’ evidence.',body,`<span>${region().waveSize===1?'One trained tree. One unfamiliar creature.':'Clear condition: correct gear for all '+region().waveSize+' enemies.'}</span><button class="primary" data-action="predict" ${!S.tree.split?'disabled':''}>${G.encounter?'Predict my equipment':'Try it on the trail'} <span aria-hidden="true">✦</span></button>`));
  }
  function split(button){if(G.mode!=='tune')return;const feature=project.features.find(f=>f.id===button.dataset.split),node=C.findNode(S.tree,G.selected);if(!node||node.depth>=S.depth)return;try{rememberTree();C.applySplit(S.tree,node.id,feature,button.dataset.threshold===''?null:Number(button.dataset.threshold),project);G.selected=editableLeaves()[0]?.id||'r';save();sound('pick');renderSidebar();renderTune();}catch(error){G.history.pop();toast(error.message);}}
  function predict(){if(!S.tree.split)return;if(!G.encounter){closeOverlay();travel('monster');return;}cancelWork();G.records=W.predictWave(S.tree,project,G.encounter.wave,G.encounter.returnPoint);G.cursor=0;G.preview=0;G.record=G.records[0];G.waveResults=[];G.waveDone=false;G.result=null;G.trace=G.record.prediction.path.length;G.chestOpen=false;renderChest();}
  function waveRoster(chest=false){if(G.records.length<2)return'';return '<ol class="wave-roster" aria-label="Wave enemies">'+G.records.map((r,i)=>{const result=G.waveResults[i],status=result?(result.correct?'Correct gear':'Wrong gear'):(chest?'Prediction preview':i===G.cursor?'Current enemy':'Waiting');return '<li aria-label="'+escape(r.monster.name)+': '+status+'" class="'+(i===(chest?G.preview:G.cursor)?'current ':'')+(result?(result.correct?'beaten':'missed'):'')+'">'+(chest?'<button data-preview="'+i+'" aria-label="Inspect prediction for '+escape(r.monster.name)+'">':'<div>')+'<img src="'+foeImg(r.monster)+'" alt=""><span>'+(i+1)+'. '+escape(r.monster.name)+'</span>'+(G.chestOpen?gear(r.gearId,true):'<b>?</b>')+(result?'<small class="wave-outcome">'+(result.correct?'✓ Correct':'! Wrong')+'</small>':'')+(chest?'</button>':'</div>')+'</li>';}).join('')+'</ol>';}
  function waveProgress(){if(G.records.length<2)return'';const correct=G.waveResults.filter(r=>r.correct).length;return '<div class="wave-progress" role="status"><strong>'+correct+' / '+G.records.length+' predictions correct</strong><span>'+(G.waveDone?(correct===G.records.length?'Wave cleared.':'Retune and retry: every enemy needs the right gear.'):'Every enemy needs the right gear to clear the wave.')+'</span></div>';}
  function renderChest(){const record=G.record;if(!record)return;const pred=record.prediction,path=pred.path.slice(0,G.trace+1),item=Q.GEAR[record.gearId];show('chest',shell('A question. A choice. A little magic.','The Tree is choosing from its learned branches.',`${waveRoster(true)}<div class="chest-layout"><div class="chest-scene ${G.chestOpen?'is-open':''}"><div class="chest-light"></div><div class="chest-particles" aria-hidden="true">✦ <span>✧</span> ✦</div><div class="revealed-item">${G.chestOpen?gear(record.gearId,true):''}</div><div class="chest-figure" aria-hidden="true"><div class="chest-shadow"></div><div class="chest-lid"><i></i></div><div class="chest-base"><i></i><b></b></div><span class="chest-lock">◆</span></div><div class="gear-reveal" aria-live="polite">${G.chestOpen?`<span>The Tree chose</span><h3 data-testid="revealed-gear">${item.label}</h3><p>Selected from your actual decision tree.</p>`:'<span>The enchanted chest</span><h3>Your tree holds the key.</h3><p>Open it to discover its prediction.</p>'}</div></div><section class="prediction-proof"><span class="section-label">The path behind the magic</span><h3>${escape(record.monster.name)}</h3>${chips(record.monster)}<div class="proof-tree">${treeSvg(record.tree,record.project,{path})}</div><ol class="decision-path">${pred.decisions.map(d=>`<li><span>${escape(d.question)}</span><strong>${d.answer}</strong></li>`).join('')}</ol><p class="muted">Opening this chest doesn’t change the tree. The equipment can still be wrong.</p></section></div>`,`<button class="text-button" data-action="${G.chestOpen?'tune':'skip-reveal'}">${G.chestOpen?'Revisit my question':'Skip reveal'}</button>${G.chestOpen?`<button class="primary" data-action="fight">Equip & face the creature <span aria-hidden="true">⚔</span></button>`:'<button class="primary gold" data-action="open-chest">Open the chest <span aria-hidden="true">✦</span></button>'}`));}
  function openChest(){if(G.mode!=='chest'||!G.record||G.chestOpen)return;cancelWork();G.trace=G.record.prediction.path.length;G.chestOpen=true;S.lastGear=G.record.gearId;save();sound('open');renderSidebar();renderChest();}
  function fight(){if(G.mode!=='chest'||!G.chestOpen||!G.records.length)return;cancelWork();G.cursor=0;G.record=G.records[0];G.result=null;S.lastGear=G.record.gearId;save();renderSidebar();renderBattle();schedule(resolveFight,instant()?0:650);}
  function nextEnemy(){if(G.mode!=='battle'||!G.result||G.waveDone)return;cancelWork();G.cursor++;G.record=G.records[G.cursor];G.result=null;S.lastGear=G.record.gearId;save();renderSidebar();renderBattle();schedule(resolveFight,instant()?0:650);}
  function resolveFight(){if(G.mode!=='battle'||G.result||!G.record)return;cancelWork();G.result=W.resolve(G.record,S.hearts);S.hearts=G.result.hearts;G.waveResults.push({...G.result,name:G.record.monster.name});G.waveDone=S.hearts===0||G.cursor===G.records.length-1;const cleanWin=G.waveDone&&G.waveResults.length===G.records.length&&G.waveResults.every(r=>r.correct);if(cleanWin){if(!S.completed.includes(S.trial))S.completed=[...S.completed,S.trial].slice(-1000);if(!S.clearedLevels.includes(S.level))S.clearedLevels.push(S.level);S.unlocked=Math.max(S.unlocked,Math.min(4,S.level+1));}save();sound(G.result.correct?'hit':'miss');renderSidebar();renderMonster();renderBattle();say(cleanWin?(S.level===4?(S.clearedLevels.length===5?'Campaign complete. All five chapters cleared.':'Final wave cleared.'):'Wave cleared. The next region is unlocked.'):G.result.correct?'The predicted equipment defeated this creature.':'The prediction was wrong. Follow the branch and improve your tree.');}
  function renderBattle(){const record=G.record,r=G.result,foe=record.monster,multi=G.records.length>1,allCorrect=G.waveResults.every(r=>r.correct),won=G.waveDone&&allCorrect&&G.waveResults.length===G.records.length,finished=won&&S.clearedLevels.length===5&&S.level===4;const explanation=record.prediction.decisions.map(d=>d.question+' '+d.answer+'.').join(' '),title=!r?'Put your teaching to the test':multi&&G.waveDone?(won?(finished?'Wave cleared. Campaign complete.':'Wave cleared.'):S.hearts===0?'Retreat and regroup.':'A branch needs tending.'):(r.correct?'A good question paid off.':'A mistake is a clue. Keep going.');
    show('battle',shell(title,multi?'Enemy '+(G.cursor+1)+' of '+G.records.length+' · One trained tree chooses every weapon.':r?(r.correct?'Your predicted equipment matched this creature.':'Your tree chose the wrong equipment. Follow the clue and try again.'):'Your hero uses the Tree’s actual prediction.',`${finished?'<section class="campaign-complete" role="status"><span aria-hidden="true">♛</span><div><h3>Campaign complete</h3><p>All five chapters cleared. The living kingdom is safe.</p></div></section>':''}${waveProgress()}${waveRoster()}<div class="battle-arena ${r?'resolved':''} ${r?.correct&&(!G.waveDone||won)?'won':''}"><div class="arena-landscape"></div><div class="battle-hero"><img src="${heroImg(r?(G.waveDone&&!won?'hurt':r.correct?'cheer0':'hurt'):'attack1')}" alt="${HEROES[S.hero].name}"><span>${HEROES[S.hero].name}</span></div><div class="battle-gear ${r?'settled':''}">${gear(record.gearId,true)}</div><div class="battle-monster ${r?.correct?'defeated':''}"><img src="${foeImg(foe)}" alt="${escape(foe.name)}"><span>${escape(foe.name)}</span></div>${r?'<div class="battle-impact '+(r.correct?'':'miss')+'">'+(won?(finished?'Kingdom restored':'Wave cleared'):G.waveDone?'Retune and retry':r.correct?'Well chosen!':'Follow this clue')+'</div>':''}</div><div class="battle-evidence"><div><span class="section-label">Your tree’s choice</span><h3>${gear(record.gearId)}</h3><p>${escape(explanation)}</p></div><div><span class="section-label">What happened</span><h3>${r?(r.correct?'Creature defeated':'It needed the '+Q.GEAR[r.required].label):'The prediction is being tested.'}</h3><p>${!r?'Combat tests your chosen equipment; it never replaces the prediction.':won?(S.level<4?'The next region is ready. Journey onward from your quest tracker.':'The kingdom is safe. You have completed all five lessons.'):G.waveDone&&!allCorrect?'A wave clears when every prediction works. Retune your tree and try again.':r.correct?'This branch worked. A different creature is the next test.':'Compare the selected leaf with the creature’s clues, then improve the question.'}</p></div></div>`,`<span class="battle-hearts" aria-label="${S.hearts} hearts remaining">${'♥ '.repeat(S.hearts)}${'♡ '.repeat(3-S.hearts)}</span>${r?'<div class="footer-actions">'+(!won?'<button class="secondary" data-action="improve">'+(multi?'Retune the tree':'Try another question')+'</button>':'')+(!G.waveDone?'<button class="primary" data-action="next-enemy">Next enemy <span aria-hidden="true">→</span></button>':'<button class="primary" data-action="return-world">Return to the world <span aria-hidden="true">↗</span></button>')+'</div>':'<button class="secondary" data-action="skip-battle">Skip animation</button>'}`));}
  function renderWorld(){const foe=W.wave(S.level,S.trial)[0];$('world-stage').innerHTML=window.AdventureArt().replace('Forest Trail',escape(region().trail))+`<button class="world-landmark scout-landmark" style="left:250px;top:405px;z-index:405" data-landmark="scout" aria-label="Walk to Scout camp"><span class="landmark-pin">✎</span><span class="landmark-label">Scout camp</span></button><button class="world-landmark tree-landmark" style="left:570px;top:285px;z-index:285" data-landmark="tree" aria-label="Walk to the Wise Tree"><img src="${A}icons/wise-tree.png" alt="The Wise Tree"><span class="tree-aura" aria-hidden="true"></span><span class="landmark-label">The Wise Tree</span></button><button id="world-monster" class="world-landmark monster-landmark" style="left:${W.LANDMARKS.monster.x}px;top:${W.LANDMARKS.monster.y}px;z-index:${W.LANDMARKS.monster.y}" data-landmark="monster" aria-label="Walk to ${escape(foe.name)}"><span class="enemy-mark">!</span><img src="${foeImg(foe)}" alt="${escape(foe.name)}"><span class="landmark-label">${escape(foe.name)}</span></button><div id="world-player" class="world-player" style="z-index:565"><span class="player-shadow"></span><img class="hero-sprite" src="${heroImg('idle')}" alt="${HEROES[S.hero].name}, your hero"><span class="player-name">${HEROES[S.hero].name}</span></div>`;renderMonster();paint();}
  function renderMonster(){const el=$('world-monster');if(!el)return;const foe=W.wave(S.level,S.trial)[0],done=S.completed.includes(S.trial);el.classList.toggle('is-defeated',done);el.querySelector('img').src=foeImg(foe);el.querySelector('img').alt=foe.name;el.querySelector('.enemy-mark').textContent=done?'✓':'!';el.querySelector('.landmark-label').textContent=done?'Encounter complete':foe.name;el.setAttribute('aria-label',done?'Walk to the completed encounter':`Walk to ${foe.name}`);}
  function renderSidebar(){const won=S.completed.length,steps=[['Meet the creatures',S.visits.includes('monster')],['Tend the Wise Tree',!!S.tree.split],['Win '+(region().waveSize>1?'the '+region().waveSize+'-enemy wave':'your first encounter'),won>0]];$('quest-steps').innerHTML=steps.map(([label,done],i)=>'<li class="'+(done?'done':'')+'"><span>'+(done?'✓':i+1)+'</span>'+label+'</li>').join('');$('quest-title').textContent=S.clearedLevels.length===5&&S.level===4?'Campaign complete':region().quest;$('quest-description').textContent=S.clearedLevels.length===5&&S.level===4?'All five chapters are cleared. Explore the kingdom or practise with a fresh wave.':region().goal;$('region-name').textContent=region().name;$('region-lesson').textContent='Chapter '+(S.level+1)+' · '+region().lesson;$('hero-name').textContent=HEROES[S.hero].name;$('hero-rank').textContent='Treekeeper · '+S.clearedLevels.length+' / 5 chapters';$('encounter-count').textContent=won+' '+(won===1?'victory':'victories');$('equipment-slot').innerHTML=S.lastGear?gear(S.lastGear):'<span class="empty-equipment">✧</span><span>Awaiting the Tree’s choice</span>';$('hearts').innerHTML='<span>'+'♥ '.repeat(S.hearts)+'</span><span class="empty-hearts">'+'♡ '.repeat(3-S.hearts)+'</span>';$('hearts').setAttribute('aria-label',S.hearts+' hearts remaining');$('avatar').src=heroImg('idle');$('hero-portrait').src=heroImg('idle');document.body.dataset.biome=S.level;const primary=document.querySelector('.trail-button'),done=S.completed.includes(S.trial);primary.dataset.action=done?'fresh':'';primary.dataset.travel=done?'':'monster';primary.innerHTML=done?'Find a fresh '+(S.level?'wave':'encounter'):'Follow the '+(S.level?'warpath':'forest trail');const next=$('next-region');next.hidden=!S.clearedLevels.includes(S.level)||S.level===4;next.textContent='Journey to '+(W.REGIONS[S.level+1]?.name||'the kingdom');$('chapter-progress').style.transform='scaleX('+S.clearedLevels.length/5+')';$('minimap-name').textContent=region().name;}
  function caption(speaker,text){$('world-caption').innerHTML=`<span class="caption-avatar">♧</span><div><strong>${escape(speaker)}</strong><p>${escape(text)}</p></div>`;}
  function updateNearby(force=false){const near=W.nearby(S.position),changed=near?.id!==G.near?.id;G.near=near;if(!changed&&!force)return;const host=$('interaction');if(!near||!S.started||G.mode){host.innerHTML='';return;}const label=near.id==='monster'?(S.completed.includes(S.trial)?'A fresh encounter awaits':'Engage the creature'):near.id==='tree'?'Tend the Wise Tree':'Read Pip’s scout reports';host.innerHTML=`<button data-action="interact"><kbd>E</kbd><span>${label}</span><b>↗</b></button>`;}
  function paint(){const host=$('world'),width=host.clientWidth,height=host.clientHeight,scale=Math.max(width/W.WORLD.width,height/W.WORLD.height,1);G.camera.scale=scale;G.camera.x=Math.max(0,Math.min(W.WORLD.width-width/scale,S.position.x-width/scale*.5));G.camera.y=Math.max(0,Math.min(W.WORLD.height-height/scale,S.position.y-height/scale*.54));$('world-stage').style.transform='scale('+scale+') translate('+(-G.camera.x)+'px,'+(-G.camera.y)+'px)';const player=$('world-player');if(player){player.style.transform='translate('+S.position.x+'px,'+S.position.y+'px) translate(-50%,-100%)';player.style.zIndex=String(Math.round(S.position.y));player.dataset.x=S.position.x.toFixed(2);player.dataset.y=S.position.y.toFixed(2);}$('location-name').textContent=S.position.x>790?region().trail:S.position.x>460?'Ancient Grove':'Village Square';$('world').dataset.location=$('location-name').textContent;const marker=$('minimap-marker');if(marker)marker.setAttribute('transform','translate('+S.position.x+' '+S.position.y+')');updateNearby();}
  function travel(id){if(!S.started){chooseCharacters();return;}if(G.mode)closeOverlay();const target=id==='village'?W.WORLD.spawn:W.LANDMARKS[id]?.target;if(!target)return;G.path=W.pathfind(S.position,target);if(!G.path.length){toast('That path is blocked. Click a clear part of the trail.');return;}caption('A path worth following',id==='monster'?'Walk up to the creature, then choose Engage or press E.':id==='tree'?'The Wise Tree can only learn from the observations you give it.':id==='scout'?'Pip’s journal records past creatures and the equipment that worked.':'Take your time. The kingdom is here to explore.');$('world').focus({preventScroll:true});}
  function interact(){if(G.mode||!S.started)return;const near=W.nearby(S.position);if(!near)return toast('Walk a little closer to the Tree, scout camp or creature.');if(!S.visits.includes(near.id))S.visits.push(near.id);if(near.id==='monster'){if(S.completed.includes(S.trial))freshEncounter();else enterEncounter();}else if(near.id==='tree')tune();else openJournal();save();renderSidebar();}
  function openJournal(){cancelWork();if(!S.visits.includes('scout'))S.visits.push('scout');save();renderSidebar();show('journal',shell('Pip’s scout journal',project.rows.length+' observations · '+region().lesson,`<div class="journal-intro"><span class="journal-stamp">Training examples</span><h3>Look for a pattern in the clues.</h3><p>These are past observations. Your wave’s creatures never become training notes automatically.</p><div class="lesson-guidance" role="note">${escape(lessonGuidance())}</div><div class="evidence-tools">${evidenceTools()}</div></div><div class="notes-grid">${noteCards()}</div>`,`<span>${S.level===3?3-S.checked.length+' report checks remaining.':'Learn from the reports, then test unfamiliar creatures.'}</span><button class="primary" data-action="tune">Visit the Wise Tree ↗</button>`));}
  function freshEncounter(){cancelWork();if(G.mode)closeOverlay();S.trial=Math.min(100000,S.trial+1);if(S.hearts===0)S.hearts=3;G.record=null;G.result=null;renderMonster();renderSidebar();updateNearby(true);save();caption('A new test of your teaching',S.level?'A fresh wave awaits. Your trained tree is ready.':'A fresh creature is waiting on the trail. Your tree has kept its question.');say('A fresh creature is now on the forest trail.');}
  function help(){cancelWork();show('help',shell('A little guidance.','Explore, wonder, and let the evidence lead.',`<ol class="help-list"><li><strong>Explore.</strong> Click the ground to walk, or use WASD/arrows. Paths go around solid obstacles.</li><li><strong>Inspect.</strong> Approach a creature and press E or click the nearby prompt. Passing by won’t start a battle.</li><li><strong>Teach.</strong> Read the scout reports and choose a question for the Wise Tree.</li><li><strong>Discover.</strong> Open the chest. It reveals the real prediction, even when it’s wrong.</li><li><strong>Try again.</strong> Trace the choice, improve your question, then test a fresh encounter.</li></ol><div class="note-box">Five chapters teach examples, tree depth, missing clues, noisy labels and rare classes. Clear each region to unlock the next.</div><p class="muted">Escape leaves a conversation or encounter. Settings includes quiet sound, reduced motion, export and reset. Progress saves locally in this browser.</p>`,`<button class="primary" data-action="close">Back to exploring ↗</button>`,false));}
  function settings(confirm=false){cancelWork();show('settings',shell(confirm?'A fresh adventure?':'Make yourself at home.',confirm?'Your current Tree, victories and hero choice will be cleared.':'A few small things for your adventure.',confirm?'<p class="settings-description">You can export your progress before starting over. This resets the current adventure campaign; the standalone lab is unaffected.</p>':`<div class="settings-list"><label><span><strong>Mute sound</strong><small>Gentle footsteps and magical cues are optional.</small></span><input id="setting-mute" type="checkbox" ${S.muted?'checked':''}></label><label><span><strong>Reduced motion</strong><small>Instant reveals, no decorative steps or moving effects.</small></span><input id="setting-reduced" type="checkbox" ${S.reduced?'checked':''}></label></div><p class="settings-description">Your hero, position, learned question, hearts and victories save on this device. Reloading during an encounter returns to the world checkpoint.</p><div class="settings-actions"><button class="secondary" data-action="export">Export adventure</button><button class="text-button" data-action="reset-confirm">Start a fresh adventure</button></div><p class="game-links"><a href="./index.html">Decision tree lab</a> · <a href="./campaign.html">Original campaign</a> · <a href="./assets/woodland/monsters/SOURCES.json">Art credits</a></p>${G.teacher?'<div class="note-box"><strong>Teacher mode</strong><p>Jump straight to the creature for a demonstration. Outcomes still use the actual chosen split.</p><button class="secondary" data-action="teacher-encounter">Open an encounter</button><p><a href="./campaign.html#teacher">All five original lessons ↗</a></p></div>':''}`,confirm?'<button class="secondary" data-action="settings">Keep my adventure</button><button class="primary" data-action="reset">Yes, start fresh</button>':'<button class="primary" data-action="close">Back to exploring ↗</button>',false));}
  function locationMap(){cancelWork();show('map',shell('The living kingdom','Five chapters. Better questions. A kingdom to protect.',`<div class="kingdom-regions">${W.REGIONS.map((r,i)=>'<button class="region-card '+(S.level===i?'selected':'')+'" data-region="'+i+'" '+(i>S.unlocked&&!G.teacher?'disabled':'')+'><span class="region-medallion">'+(S.clearedLevels.includes(i)?'✓':i+1)+'</span><div><h3>'+r.name+'</h3><p>'+r.lesson+'</p><small>'+(i>S.unlocked&&!G.teacher?'Complete the previous chapter':r.waveSize+' '+(r.waveSize===1?'enemy':'enemies')+' · up to '+r.maxDepth+' questions per path')+'</small></div>'+(S.level===i?'<b>Current</b>':'')+'</button>').join('')}</div><div class="map-destinations"><h3>Walk to a landmark</h3><div class="location-options"><button data-travel="village">Village Square</button><button data-travel="scout">Scout camp</button><button data-travel="tree">Ancient Grove</button><button data-travel="monster">${region().trail}</button></div></div>`,`<span>${G.teacher?'Teacher demonstration: all chapters available.':'Clear the current encounter or wave to unlock the next chapter.'}</span><button class="secondary" data-action="close">Return to the world</button>`));}
  function journey(level){if(level===S.level){closeOverlay();return;}try{closeOverlay();if(G.teacher)S.unlocked=4;S=W.changeLevel(S,level);project=W.projectFor(S.level,S);G.history=[];G.selected='r';renderWorld();renderSidebar();save();caption(region().name,region().goal);toast('Chapter '+(S.level+1)+' · '+region().name);}catch(error){toast(error.message);}}
  function fullscreen(){if(document.fullscreenElement)document.exitFullscreen().catch(()=>{});else document.documentElement.requestFullscreen().catch(()=>toast('Your browser could not enter full screen. The game still fills this window.'));}
  function exportSave(){try{const blob=new Blob([JSON.stringify(W.restore(S),null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='treequest-woodland-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}catch(error){toast(error.message);}}
  function reset(){cancelWork();try{Store.reset();}catch{toast('Browser storage is unavailable. Starting a fresh adventure for this session.');}S=W.fresh();project=W.projectFor(S.level,S);G.history=[];G.encounter=null;G.record=null;G.result=null;renderWorld();renderSidebar();chooseCharacters();}
  const actions={
    begin(){S.started=true;save();closeOverlay();renderWorld();renderSidebar();caption('The Wise Tree','Welcome, Treekeeper. Explore the grove, read the scouts’ notes, or follow the forest trail.');},
    close(){if(S.started)closeOverlay();},explore(){if(S.started)closeOverlay();else chooseCharacters();},characters:chooseCharacters,interact,inspect:enterEncounter,tune,tree:tune,journal:openJournal,help,settings,map:locationMap,export:exportSave,
    predict,fullscreen,'retry-reports':restartReports,'next-enemy':nextEnemy,'next-region'(){journey(Math.min(4,S.level+1));},
    'grow-one'(){rememberTree();C.growStep(S.tree,project,S.depth);G.selected=editableLeaves()[0]?.id||'r';save();renderSidebar();renderTune();},
    'auto-tree'(){rememberTree();S.tree=C.train(project,S.depth);G.selected=editableLeaves()[0]?.id||'r';save();renderSidebar();renderTune();},
    'undo-tree'(){if(!G.history.length)return;S.tree=G.history.pop();G.selected=editableLeaves()[0]?.id||'r';save();renderSidebar();renderTune();},
    'reveal-clue'(){if(S.level!==2||S.revealed)return;S.revealed=true;rebuildEvidence('Shadow is now an observable feature. Rebuild the tree with this clue.');},
    'send-scouts'(){if(S.level!==4||S.scoutRounds>=2)return;S.scoutRounds++;rebuildEvidence('The scouts brought three new shadow reports. Rebuild from the stronger evidence.');},
    'open-chest':openChest,'skip-reveal':openChest,fight,'skip-battle':resolveFight,'return-world':closeOverlay,
    improve(){S.hearts=3;G.record=null;G.records=[];G.waveResults=[];G.result=null;tune();},'reset-tree'(){rememberTree();S.tree=C.newTree(project);G.selected='r';save();renderSidebar();renderTune();},fresh:freshEncounter,
    'reset-confirm'(){settings(true);},reset,pause(){cancelWork();show('pause',shell('A moment under the trees.','Your adventure can wait a little.',`<div class="pause-content"><span>Ⅱ</span><p>Take a breath. Your hero and learned question are safe.</p></div>`,'<button class="primary" data-action="close">Keep exploring ↗</button>',false));},
    'teacher-encounter'(){closeOverlay();S.position={...W.LANDMARKS.monster.target};if(S.completed.includes(S.trial))S.trial++;paint();enterEncounter();}
  };
  document.addEventListener('click',event=>{const leaf=event.target.closest('[data-node]');if(leaf&&G.mode==='tune'){G.selected=leaf.dataset.node;renderTune();$('overlay-content').querySelector('[data-split]')?.focus();return;}const button=event.target.closest('button');if(button){if(button.disabled)return;if(button.dataset.region!==undefined){journey(Number(button.dataset.region));return;}if(button.dataset.check){if(S.level!==3||S.checked.includes(button.dataset.check)||S.checked.length>=3)return;checkReport(button.dataset.check);return;}if(button.dataset.preview!==undefined&&G.mode==='chest'){G.preview=Number(button.dataset.preview);G.record=G.records[G.preview];G.trace=G.record.prediction.path.length;renderChest();return;}if(button.dataset.action&&actions[button.dataset.action]){actions[button.dataset.action]();return;}if(button.dataset.hero){S.hero=button.dataset.hero;save();renderWorld();renderSidebar();chooseCharacters();return;}if(button.dataset.split){split(button);return;}if(button.dataset.tab){G.panel=button.dataset.tab;renderTune();$('overlay-content').querySelector('[role=tab][data-tab='+G.panel+']')?.focus();return;}if(button.dataset.travel){travel(button.dataset.travel);return;}if(button.dataset.landmark){const id=button.dataset.landmark;if(W.distance(S.position,W.LANDMARKS[id])<115){if(id==='monster')S.completed.includes(S.trial)?freshEncounter():enterEncounter();else if(id==='tree')tune();else openJournal();}else travel(id);return;}}
    if(G.mode||!S.started||!event.target.closest('#world'))return;const bounds=$('world').getBoundingClientRect(),target={x:(event.clientX-bounds.left)/G.camera.scale+G.camera.x,y:(event.clientY-bounds.top)/G.camera.scale+G.camera.y};G.path=W.pathfind(S.position,target);if(!G.path.length){toast('Click a clear spot on the trail.');return;}const marker=$('walk-marker');marker.style.transform=`translate(${event.clientX-bounds.left}px,${event.clientY-bounds.top}px)`;marker.classList.add('visible');setTimeout(()=>marker.classList.remove('visible'),600);$('world').focus({preventScroll:true});
  });
  const keyVectors={w:[0,-1],ArrowUp:[0,-1],s:[0,1],ArrowDown:[0,1],a:[-1,0],ArrowLeft:[-1,0],d:[1,0],ArrowRight:[1,0]};
  document.addEventListener('keydown',event=>{G.keyboard=true;document.body.dataset.keyboard='true';if(event.metaKey||event.ctrlKey||event.altKey)return;if(G.mode){if(event.target.closest('[data-node]')&&['Enter',' '].includes(event.key)){event.preventDefault();G.selected=event.target.closest('[data-node]').dataset.node;renderTune();$('overlay-content').querySelector('[data-split]')?.focus();return;}if(G.mode==='tune'&&event.target.getAttribute('role')==='tab'&&['ArrowLeft','ArrowRight'].includes(event.key)){event.preventDefault();G.panel=G.panel==='tree'?'notes':'tree';renderTune();$('overlay-content').querySelector(`[role="tab"][data-tab="${G.panel}"]`)?.focus();}return;}if(/INPUT|TEXTAREA|SELECT/.test(event.target.tagName)||event.target.isContentEditable)return;const shortcuts={j:openJournal,t:tune,m:locationMap,f:fullscreen,p:actions.pause};if(shortcuts[event.key.toLowerCase()]){event.preventDefault();shortcuts[event.key.toLowerCase()]();return;}if(event.key==='Escape'){event.preventDefault();actions.pause();return;}if(event.key.toLowerCase()==='e'){event.preventDefault();interact();return;}const key=event.key.length===1?event.key.toLowerCase():event.key;if(keyVectors[key]){event.preventDefault();G.keys.add(key);G.path=[];}});
  document.addEventListener('keyup',event=>{G.keys.delete(event.key.length===1?event.key.toLowerCase():event.key);if(!G.keys.size)save();});document.addEventListener('pointerdown',()=>{G.keyboard=false;document.body.dataset.keyboard='false';});
  document.addEventListener('change',event=>{if(event.target.id==='tree-depth'){const depth=Number(event.target.value);if(!Number.isInteger(depth)||depth<1||depth>region().maxDepth)return;S.depth=depth;G.history=[];if(C.walk(S.tree).some(n=>n.depth>depth)){S.tree=C.newTree(project);G.history=[];toast('Depth reduced. Choose questions for the new tree.');}G.selected=editableLeaves()[0]?.id||'r';save();renderSidebar();renderTune();return;}if(event.target.id==='setting-mute'){S.muted=event.target.checked;if(audio)audio.master.gain.value=S.muted?0:.22;if(!S.muted)sound('pick');save();}if(event.target.id==='setting-reduced'){S.reduced=event.target.checked;document.body.dataset.reduced=String(reduced());save();}});
  $('overlay').addEventListener('cancel',event=>{event.preventDefault();if(S.started)closeOverlay();});window.addEventListener('blur',()=>{G.keys.clear();G.path=[];if(S.started)save();});window.addEventListener('pagehide',()=>{if(S.started)save();});window.addEventListener('resize',paint);
  let wasMoving=false;
  function frame(now){const dt=Math.min(.05,G.lastTime?(now-G.lastTime)/1000:0);G.lastTime=now;let moving=false;const old={...S.position};if(S.started&&!G.mode){let v={x:0,y:0};G.keys.forEach(k=>{v.x+=keyVectors[k][0];v.y+=keyVectors[k][1];});if(v.x||v.y){S.position=W.move(S.position,v,dt);}else if(G.path.length){const goal=G.path[0],dist=W.distance(S.position,goal);if(dist<4){S.position={...goal};G.path.shift();}else{S.position=W.move(S.position,{x:goal.x-S.position.x,y:goal.y-S.position.y},Math.min(dt,dist/215));if(W.distance(S.position,old)<.01)G.path=[];}}moving=W.distance(old,S.position)>.01;G.stepDistance+=W.distance(old,S.position);if(G.stepDistance>65){G.stepDistance=0;sound('step');}}
    const player=$('world-player');player?.classList.toggle('walking',moving&&!reduced());if(moving||wasMoving||!G.lastPaint){paint();G.lastPaint=true;}if(wasMoving&&!moving)save();wasMoving=moving;requestAnimationFrame(frame);
  }
  document.body.dataset.reduced=String(reduced());renderWorld();renderSidebar();requestAnimationFrame(frame);if(!S.started)chooseCharacters();else{save();caption('Welcome back, Treekeeper.','Your tree and progress in '+region().name+' are right where you left them.');}if(loaded.warning)toast(loaded.warning);
})();
